    SELECT 1
    FROM `rps_openworld_spawn_migration`
    WHERE `migration_version` = '2026_08_08_00_map_openworld_spawns'
      AND `input_sha256` <> '87de10705bf297e9b9cd7b3b0a34f11ca2277f7caabb1f193fe17f398a92c528'
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'RPS openworld spawn migration inventory SHA mismatch';
  END IF;
END//
DELIMITER ;
CALL `rps_openworld_assert_apply`();
DROP PROCEDURE `rps_openworld_assert_apply`;


