    SELECT COUNT(*)
    FROM `rps_openworld_spawn_target_map`
    WHERE `migration_version` = '2026_08_08_00_map_openworld_spawns'
  ) <> 539 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'RPS openworld spawn migration target-map scope mismatch';
  END IF;
END//
