-- Snapshot before every destructive/update operation. INSERT IGNORE preserves
-- the first baseline when apply is run more than once with this input SHA.
SELECT '2026_08_08_00_map_openworld_spawns', c.`guid`, c.`map`, c.`spawnDifficulties`
FROM `creature` c
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = c.`map`
WHERE c.`spawnDifficulties` <> '0';

SELECT '2026_08_08_00_map_openworld_spawns', g.`guid`, g.`map`, g.`spawnDifficulties`
FROM `gameobject` g
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = g.`map`
WHERE g.`spawnDifficulties` <> '0';

SELECT '2026_08_08_00_map_openworld_spawns', a.`SpawnId`, a.`MapId`, a.`SpawnDifficulties`
FROM `areatrigger` a
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = a.`MapId`
WHERE a.`SpawnDifficulties` <> '0';

-- Template difficulty 0 is copied from the lowest difficulty present on an
-- affected spawn when possible, otherwise from the template's lowest non-zero
-- row. No template ScriptName/AIName or loot-table row is edited.
SELECT
  '2026_08_08_00_map_openworld_spawns',
  affected.`entry`,
  CASE
    WHEN EXISTS (
      SELECT 1 FROM `creature_template_difficulty` zero_row
      WHERE zero_row.`Entry` = affected.`entry` AND zero_row.`DifficultyID` = 0
    ) THEN 0
    ELSE COALESCE(
      (
        SELECT MIN(matched.`DifficultyID`)
        FROM `creature_template_difficulty` matched
        JOIN `creature` matched_creature
          ON matched_creature.`id` = affected.`entry`
        JOIN `rps_openworld_spawn_target_map` matched_map
          ON matched_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
         AND matched_map.`map_id` = matched_creature.`map`
        WHERE matched.`Entry` = affected.`entry`
          AND matched.`DifficultyID` <> 0
          AND FIND_IN_SET(CAST(matched.`DifficultyID` AS CHAR), REPLACE(matched_creature.`spawnDifficulties`, ' ', '')) > 0
      ),
      (
        SELECT MIN(fallback_row.`DifficultyID`)
        FROM `creature_template_difficulty` fallback_row
        WHERE fallback_row.`Entry` = affected.`entry` AND fallback_row.`DifficultyID` <> 0
      )
    )
  END,
  CASE
    WHEN EXISTS (
      SELECT 1 FROM `creature_template_difficulty` zero_row
      WHERE zero_row.`Entry` = affected.`entry` AND zero_row.`DifficultyID` = 0
    ) THEN 'already_difficulty_0'
    WHEN EXISTS (
      SELECT 1
      FROM `creature_template_difficulty` matched
      JOIN `creature` matched_creature
        ON matched_creature.`id` = affected.`entry`
      JOIN `rps_openworld_spawn_target_map` matched_map
        ON matched_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
       AND matched_map.`map_id` = matched_creature.`map`
      WHERE matched.`Entry` = affected.`entry`
        AND matched.`DifficultyID` <> 0
        AND FIND_IN_SET(CAST(matched.`DifficultyID` AS CHAR), REPLACE(matched_creature.`spawnDifficulties`, ' ', '')) > 0
    ) THEN 'matching_spawn_difficulty'
    WHEN EXISTS (
      SELECT 1 FROM `creature_template_difficulty` fallback_row
      WHERE fallback_row.`Entry` = affected.`entry` AND fallback_row.`DifficultyID` <> 0
    ) THEN 'fallback_lowest_template_difficulty'
    ELSE 'missing_template_difficulty'
  END,
  CASE
    WHEN EXISTS (
      SELECT 1 FROM `creature_template_difficulty` zero_row
      WHERE zero_row.`Entry` = affected.`entry` AND zero_row.`DifficultyID` = 0
    ) THEN 0
    WHEN EXISTS (
      SELECT 1 FROM `creature_template_difficulty` fallback_row
      WHERE fallback_row.`Entry` = affected.`entry` AND fallback_row.`DifficultyID` <> 0
    ) THEN 1
    ELSE 0
  END
FROM (
  SELECT DISTINCT c.`id` AS `entry`
  FROM `creature` c
  JOIN `rps_openworld_spawn_target_map` m
    ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = c.`map`
) affected;

  `Entry`, `DifficultyID`, `LevelScalingDeltaMin`, `LevelScalingDeltaMax`, `ContentTuningID`,
  `HealthScalingExpansion`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `DamageModifier`,
  `CreatureDifficultyID`, `TypeFlags`, `TypeFlags2`, `TypeFlags3`, `LootID`, `PickPocketLootID`,
  `SkinLootID`, `GoldMin`, `GoldMax`, `StaticFlags1`, `StaticFlags2`, `StaticFlags3`,
  `StaticFlags4`, `StaticFlags5`, `StaticFlags6`, `StaticFlags7`, `StaticFlags8`, `VerifiedBuild`
)
SELECT
  source.`Entry`, 0, source.`LevelScalingDeltaMin`, source.`LevelScalingDeltaMax`, source.`ContentTuningID`,
  source.`HealthScalingExpansion`, source.`HealthModifier`, source.`ManaModifier`, source.`ArmorModifier`, source.`DamageModifier`,
  source.`CreatureDifficultyID`, source.`TypeFlags`, source.`TypeFlags2`, source.`TypeFlags3`, source.`LootID`, source.`PickPocketLootID`,
  source.`SkinLootID`, source.`GoldMin`, source.`GoldMax`, source.`StaticFlags1`, source.`StaticFlags2`, source.`StaticFlags3`,
  source.`StaticFlags4`, source.`StaticFlags5`, source.`StaticFlags6`, source.`StaticFlags7`, source.`StaticFlags8`, source.`VerifiedBuild`
FROM `creature_template_difficulty` source
JOIN `rps_openworld_template_difficulty_snapshot` snapshot
  ON snapshot.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND snapshot.`entry` = source.`Entry`
 AND snapshot.`source_difficulty_id` = source.`DifficultyID`
WHERE snapshot.`created_difficulty_zero` = 1
  AND NOT EXISTS (
    SELECT 1
    FROM `creature_template_difficulty` zero_row
    WHERE zero_row.`Entry` = source.`Entry` AND zero_row.`DifficultyID` = 0
  );

UPDATE `creature` c
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = c.`map`
SET c.`spawnDifficulties` = '0'
WHERE c.`spawnDifficulties` <> '0';

UPDATE `gameobject` g
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = g.`map`
SET g.`spawnDifficulties` = '0'
WHERE g.`spawnDifficulties` <> '0';

UPDATE `areatrigger` a
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = a.`MapId`
SET a.`SpawnDifficulties` = '0'
WHERE a.`SpawnDifficulties` <> '0';

-- Instance boss-state group records are invalid on MAP_COMMON. Archive their
-- exact rows and remove only records whose instance map is in the frozen scope.
SELECT '2026_08_08_00_map_openworld_spawns', i.`instanceMapId`, i.`bossStateId`, i.`bossStates`, i.`spawnGroupId`, i.`flags`
FROM `instance_spawn_groups` i
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = i.`instanceMapId`;

DELETE i
FROM `instance_spawn_groups` i
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = i.`instanceMapId`;

-- Manual groups become permanently active only when every resolvable member is
-- on a target map. Mixed/system/unresolved groups remain untouched and are
-- retained in the audit table for explicit operator review.
  `migration_version`, `group_id`, `group_name`, `original_group_flags`,
  `target_member_count`, `non_target_member_count`, `unresolved_member_count`,
  `eligible_for_auto_enable`
)
SELECT
  '2026_08_08_00_map_openworld_spawns', grouped.`group_id`, grouped.`group_name`, grouped.`group_flags`,
  grouped.`target_member_count`, grouped.`non_target_member_count`, grouped.`unresolved_member_count`,
  CASE
    WHEN grouped.`target_member_count` > 0
     AND grouped.`non_target_member_count` = 0
     AND grouped.`unresolved_member_count` = 0
     AND (grouped.`group_flags` & 1) = 0 THEN 1
    ELSE 0
  END
FROM (
  SELECT
    sgt.`groupId` AS `group_id`,
    sgt.`groupName` AS `group_name`,
    sgt.`groupFlags` AS `group_flags`,
    SUM(CASE WHEN target_map.`map_id` IS NOT NULL THEN 1 ELSE 0 END) AS `target_member_count`,
    SUM(CASE WHEN COALESCE(c.`map`, g.`map`) IS NOT NULL AND target_map.`map_id` IS NULL THEN 1 ELSE 0 END) AS `non_target_member_count`,
    SUM(CASE WHEN COALESCE(c.`map`, g.`map`) IS NULL THEN 1 ELSE 0 END) AS `unresolved_member_count`
  FROM `spawn_group_template` sgt
  JOIN `spawn_group` sg ON sg.`groupId` = sgt.`groupId`
  LEFT JOIN `creature` c ON sg.`spawnType` = 0 AND c.`guid` = sg.`spawnId`
  LEFT JOIN `gameobject` g ON sg.`spawnType` = 1 AND g.`guid` = sg.`spawnId`
  LEFT JOIN `rps_openworld_spawn_target_map` target_map
    ON target_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
   AND target_map.`map_id` = COALESCE(c.`map`, g.`map`)
  WHERE (sgt.`groupFlags` & 4) <> 0
  GROUP BY sgt.`groupId`, sgt.`groupName`, sgt.`groupFlags`
) grouped;

SELECT '2026_08_08_00_map_openworld_spawns', audit.`group_id`, audit.`original_group_flags`
FROM `rps_openworld_manual_spawn_group_audit` audit
WHERE audit.`migration_version` = '2026_08_08_00_map_openworld_spawns'
  AND audit.`eligible_for_auto_enable` = 1;

UPDATE `spawn_group_template` sgt
JOIN `rps_openworld_spawn_group_template_snapshot` snapshot
  ON snapshot.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND snapshot.`group_id` = sgt.`groupId`
SET sgt.`groupFlags` = snapshot.`group_flags` & ~4;

-- LoadLinkedRespawn rejects every link touching a non-instanceable map.
SELECT '2026_08_08_00_map_openworld_spawns', lr.`guid`, lr.`linkedGuid`, lr.`linkType`
FROM `linked_respawn` lr
LEFT JOIN `creature` slave_creature
  ON lr.`linkType` IN (0, 1) AND slave_creature.`guid` = lr.`guid`
LEFT JOIN `gameobject` slave_gameobject
  ON lr.`linkType` IN (2, 3) AND slave_gameobject.`guid` = lr.`guid`
LEFT JOIN `creature` master_creature
  ON lr.`linkType` IN (0, 3) AND master_creature.`guid` = lr.`linkedGuid`
LEFT JOIN `gameobject` master_gameobject
  ON lr.`linkType` IN (1, 2) AND master_gameobject.`guid` = lr.`linkedGuid`
LEFT JOIN `rps_openworld_spawn_target_map` slave_creature_map
  ON slave_creature_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND slave_creature_map.`map_id` = slave_creature.`map`
LEFT JOIN `rps_openworld_spawn_target_map` slave_gameobject_map
  ON slave_gameobject_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND slave_gameobject_map.`map_id` = slave_gameobject.`map`
LEFT JOIN `rps_openworld_spawn_target_map` master_creature_map
  ON master_creature_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND master_creature_map.`map_id` = master_creature.`map`
LEFT JOIN `rps_openworld_spawn_target_map` master_gameobject_map
  ON master_gameobject_map.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND master_gameobject_map.`map_id` = master_gameobject.`map`
WHERE slave_creature_map.`map_id` IS NOT NULL
   OR slave_gameobject_map.`map_id` IS NOT NULL
   OR master_creature_map.`map_id` IS NOT NULL
   OR master_gameobject_map.`map_id` IS NOT NULL;

DELETE lr
FROM `linked_respawn` lr
JOIN `rps_openworld_linked_respawn_archive` archived
  ON archived.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND archived.`guid` = lr.`guid`
 AND archived.`link_type` = lr.`linkType`;

VALUES ('2026_08_08_00_map_openworld_spawns', '87de10705bf297e9b9cd7b3b0a34f11ca2277f7caabb1f193fe17f398a92c528', 539)
