SELECT 'active_instance_spawn_groups', COUNT(*)
FROM `instance_spawn_groups` i
JOIN `rps_openworld_spawn_target_map` m
  ON m.`migration_version` = '2026_08_08_00_map_openworld_spawns' AND m.`map_id` = i.`instanceMapId`
