SELECT 'active_linked_respawn_touching_target', COUNT(*)
FROM `linked_respawn` lr
JOIN `rps_openworld_linked_respawn_archive` archived
  ON archived.`migration_version` = '2026_08_08_00_map_openworld_spawns'
 AND archived.`guid` = lr.`guid`
 AND archived.`link_type` = lr.`linkType`;

-- Review before production rollout; a missing source means the template had no
-- non-zero difficulty row to copy and needs a deliberately authored default.
SELECT `entry`, `source_kind`
FROM `rps_openworld_template_difficulty_snapshot`
WHERE `migration_version` = '2026_08_08_00_map_openworld_spawns'
  AND `source_kind` = 'missing_template_difficulty'
ORDER BY `entry`;

SELECT `group_id`, `group_name`, `target_member_count`, `non_target_member_count`, `unresolved_member_count`
FROM `rps_openworld_manual_spawn_group_audit`
WHERE `migration_version` = '2026_08_08_00_map_openworld_spawns'
  AND `eligible_for_auto_enable` = 0
ORDER BY `group_id`;
